SELECT c.comment_id, c.tenant_id, c.owner_type, c.owner_id, c.parent_comment_id,
       c.content, c.comment_type, c.event_type, c.writer_id, c.writer_name, c.last_modified_by,
       c.last_modified_by_name, c.deleted_yn, c.created_at, c.updated_at,

FROM tb_common_comment c

WHERE c.tenant_id = #{tenantId}
  AND c.owner_type = #{ownerType}
  AND c.owner_id = #{ownerId}
  AND c.deleted_yn = 'N'
ORDER BY c.created_at ASC

WITH RECURSIVE all_comment_tree AS ( SELECT c.comment_id, c.parent_comment_id, c.deleted_yn, c.owner_id, c.comment_id AS root_comment_id FROM tb_common_comment c WHERE c.tenant_id = #{tenantId} AND c.owner_type = #{ownerType} AND c.owner_id IN
#{ownerId}
AND c.parent_comment_id IS NULL UNION ALL SELECT child.comment_id, child.parent_comment_id, child.deleted_yn, child.owner_id, tree.root_comment_id FROM tb_common_comment child JOIN all_comment_tree tree ON tree.comment_id = child.parent_comment_id WHERE child.tenant_id = #{tenantId} AND child.owner_type = #{ownerType} AND child.owner_id IN
#{ownerId}
AND child.comment_id <> ALL(ARRAY[tree.comment_id]) ), root_page AS ( SELECT owner_id, root_comment_id AS comment_id, ROW_NUMBER() OVER (PARTITION BY owner_id ORDER BY root_comment_id DESC) AS root_order FROM all_comment_tree GROUP BY owner_id, root_comment_id HAVING BOOL_OR(deleted_yn = 'N') ), comment_tree AS ( SELECT c.comment_id, c.tenant_id, c.owner_type, c.owner_id, c.parent_comment_id, c.content, c.comment_type, c.event_type, c.writer_id, c.writer_name, c.last_modified_by, c.last_modified_by_name, c.deleted_yn, c.created_at, c.updated_at, rp.root_order, ARRAY[c.comment_id] AS comment_path FROM tb_common_comment c JOIN root_page rp ON rp.comment_id = c.comment_id AND rp.owner_id = c.owner_id WHERE rp.root_order <= #{limit} UNION ALL SELECT child.comment_id, child.tenant_id, child.owner_type, child.owner_id, child.parent_comment_id, child.content, child.comment_type, child.event_type, child.writer_id, child.writer_name, child.last_modified_by, child.last_modified_by_name, child.deleted_yn, child.created_at, child.updated_at, tree.root_order, tree.comment_path || child.comment_id FROM tb_common_comment child JOIN comment_tree tree ON tree.comment_id = child.parent_comment_id WHERE child.tenant_id = #{tenantId} AND child.owner_type = #{ownerType} AND child.owner_id IN
#{ownerId}
AND NOT child.comment_id = ANY(tree.comment_path) ) SELECT c.comment_id, c.tenant_id, c.owner_type, c.owner_id, c.parent_comment_id, c.content, c.comment_type, c.event_type, c.writer_id, c.writer_name, c.last_modified_by, c.last_modified_by_name, c.deleted_yn, c.created_at, c.updated_at,
FROM comment_tree c
ORDER BY c.owner_id, c.root_order, c.comment_path

SELECT owner_id AS ownerId, COUNT(*) AS totalCount
FROM tb_common_comment
WHERE tenant_id = #{tenantId}
  AND owner_type = #{ownerType}
  AND owner_id IN

      #{ownerId}

  AND parent_comment_id IS NULL
  AND deleted_yn = 'N'
GROUP BY owner_id

WITH RECURSIVE all_comment_tree AS ( SELECT c.comment_id, c.parent_comment_id, c.deleted_yn, c.owner_id, c.comment_id AS root_comment_id, ARRAY[c.comment_id] AS comment_path FROM tb_common_comment c WHERE c.tenant_id = #{tenantId} AND c.owner_type = 'APPROVAL' AND c.owner_id IN
#{ownerId}
AND c.comment_type = 'USER' AND c.parent_comment_id IS NULL UNION ALL SELECT child.comment_id, child.parent_comment_id, child.deleted_yn, child.owner_id, tree.root_comment_id, tree.comment_path || child.comment_id FROM tb_common_comment child JOIN all_comment_tree tree ON tree.comment_id = child.parent_comment_id WHERE child.tenant_id = #{tenantId} AND child.owner_type = 'APPROVAL' AND child.owner_id IN
#{ownerId}
AND child.comment_type = 'USER' AND NOT child.comment_id = ANY(tree.comment_path) ), root_page AS ( SELECT owner_id, root_comment_id AS comment_id, ROW_NUMBER() OVER (PARTITION BY owner_id ORDER BY root_comment_id DESC) AS root_order FROM all_comment_tree GROUP BY owner_id, root_comment_id HAVING BOOL_OR(deleted_yn = 'N') ), comment_tree AS ( SELECT c.comment_id, c.tenant_id, c.owner_type, c.owner_id, c.parent_comment_id, c.content, c.comment_type, c.event_type, c.writer_id, c.writer_name, c.last_modified_by, c.last_modified_by_name, c.deleted_yn, c.created_at, c.updated_at, rp.root_order, ARRAY[c.comment_id] AS comment_path FROM tb_common_comment c JOIN root_page rp ON rp.comment_id = c.comment_id AND rp.owner_id = c.owner_id WHERE rp.root_order <= #{limit} UNION ALL SELECT child.comment_id, child.tenant_id, child.owner_type, child.owner_id, child.parent_comment_id, child.content, child.comment_type, child.event_type, child.writer_id, child.writer_name, child.last_modified_by, child.last_modified_by_name, child.deleted_yn, child.created_at, child.updated_at, tree.root_order, tree.comment_path || child.comment_id FROM tb_common_comment child JOIN comment_tree tree ON tree.comment_id = child.parent_comment_id WHERE child.tenant_id = #{tenantId} AND child.owner_type = 'APPROVAL' AND child.owner_id IN
#{ownerId}
AND child.comment_type = 'USER' AND NOT child.comment_id = ANY(tree.comment_path) ) SELECT c.comment_id, c.tenant_id, c.owner_type, c.owner_id, c.parent_comment_id, c.content, c.comment_type, c.event_type, c.writer_id, c.writer_name, c.last_modified_by, c.last_modified_by_name, c.deleted_yn, c.created_at, c.updated_at,
FROM comment_tree c
ORDER BY c.owner_id, c.root_order, c.comment_path

SELECT owner_id AS ownerId, COUNT(*) AS totalCount FROM tb_common_comment WHERE tenant_id = #{tenantId} AND owner_type = 'APPROVAL' AND owner_id IN
#{ownerId}
AND comment_type = 'USER' AND parent_comment_id IS NULL AND deleted_yn = 'N' GROUP BY owner_id

WITH RECURSIVE user_comment_tree AS ( SELECT c.comment_id, c.owner_id, c.deleted_yn, c.comment_id AS root_comment_id, ARRAY[c.comment_id] AS comment_path FROM tb_common_comment c WHERE c.tenant_id = #{tenantId} AND c.owner_type = 'APPROVAL' AND c.owner_id IN
#{ownerId}
AND c.comment_type = 'USER' AND c.parent_comment_id IS NULL UNION ALL SELECT child.comment_id, child.owner_id, child.deleted_yn, tree.root_comment_id, tree.comment_path || child.comment_id FROM tb_common_comment child JOIN user_comment_tree tree ON tree.comment_id = child.parent_comment_id WHERE child.tenant_id = #{tenantId} AND child.owner_type = 'APPROVAL' AND child.owner_id IN
#{ownerId}
AND child.comment_type = 'USER' AND NOT child.comment_id = ANY(tree.comment_path) ), visible_user_roots AS ( SELECT root.owner_id, root.comment_id, root.created_at FROM tb_common_comment root WHERE root.tenant_id = #{tenantId} AND root.owner_type = 'APPROVAL' AND root.owner_id IN
#{ownerId}
AND root.comment_type = 'USER' AND root.parent_comment_id IS NULL AND EXISTS ( SELECT 1 FROM user_comment_tree tree WHERE tree.owner_id = root.owner_id AND tree.root_comment_id = root.comment_id GROUP BY tree.owner_id, tree.root_comment_id HAVING BOOL_OR(tree.deleted_yn = 'N') ) ), system_roots AS ( SELECT event.owner_id, event.comment_id, event.created_at FROM tb_common_comment event WHERE event.tenant_id = #{tenantId} AND event.owner_type = 'APPROVAL' AND event.owner_id IN
#{ownerId}
AND event.comment_type = 'SYSTEM' AND event.parent_comment_id IS NULL AND event.deleted_yn = 'N' ), stream_roots AS ( SELECT owner_id, comment_id, created_at, 'USER' AS comment_type FROM visible_user_roots UNION ALL SELECT owner_id, comment_id, created_at, 'SYSTEM' AS comment_type FROM system_roots )
, cursor_item AS ( SELECT c.owner_id, c.created_at, c.comment_id FROM tb_common_comment c WHERE c.tenant_id = #{tenantId} AND c.owner_type = 'APPROVAL' AND c.owner_id IN
#{ownerId}
AND c.comment_id = #{beforeCommentId} )
, eligible_roots AS ( SELECT root.owner_id, root.comment_id, root.created_at, root.comment_type FROM stream_roots root
JOIN cursor_item cursor ON cursor.owner_id = root.owner_id AND (root.created_at, root.comment_id) < (cursor.created_at, cursor.comment_id)
), ranked_roots AS ( SELECT owner_id, comment_id, created_at, ROW_NUMBER() OVER ( PARTITION BY owner_id ORDER BY created_at DESC, comment_id DESC ) AS stream_order FROM eligible_roots ) SELECT c.comment_id, c.tenant_id, c.owner_type, c.owner_id, c.parent_comment_id, c.content, c.comment_type, c.event_type, c.writer_id, c.writer_name, c.last_modified_by, c.last_modified_by_name, c.deleted_yn, c.created_at, c.updated_at,
FROM ranked_roots root JOIN tb_common_comment c ON c.comment_id = root.comment_id AND c.owner_id = root.owner_id
WHERE root.stream_order <= #{limit} ORDER BY root.owner_id, root.stream_order

WITH RECURSIVE comment_tree AS ( SELECT root.comment_id, root.tenant_id, root.owner_type, root.owner_id, root.parent_comment_id, root.content, root.comment_type, root.event_type, root.writer_id, root.writer_name, root.last_modified_by, root.last_modified_by_name, root.deleted_yn, root.created_at, root.updated_at, root.comment_id AS root_comment_id, root.created_at AS root_created_at, ARRAY[root.comment_id] AS comment_path FROM tb_common_comment root WHERE root.tenant_id = #{tenantId} AND root.owner_type = 'APPROVAL' AND root.owner_id IN
#{ownerId}
AND root.comment_id IN
#{rootId}
AND root.comment_type = 'USER' AND root.parent_comment_id IS NULL UNION ALL SELECT child.comment_id, child.tenant_id, child.owner_type, child.owner_id, child.parent_comment_id, child.content, child.comment_type, child.event_type, child.writer_id, child.writer_name, child.last_modified_by, child.last_modified_by_name, child.deleted_yn, child.created_at, child.updated_at, tree.root_comment_id, tree.root_created_at, tree.comment_path || child.comment_id FROM tb_common_comment child JOIN comment_tree tree ON tree.comment_id = child.parent_comment_id WHERE child.tenant_id = #{tenantId} AND child.owner_type = 'APPROVAL' AND child.owner_id IN
#{ownerId}
AND child.comment_type = 'USER' AND NOT child.comment_id = ANY(tree.comment_path) ) SELECT c.comment_id, c.tenant_id, c.owner_type, c.owner_id, c.parent_comment_id, c.content, c.comment_type, c.event_type, c.writer_id, c.writer_name, c.last_modified_by, c.last_modified_by_name, c.deleted_yn, c.created_at, c.updated_at,
FROM comment_tree c
ORDER BY c.owner_id, c.root_created_at, c.root_comment_id, c.comment_path

WITH RECURSIVE user_comment_tree AS ( SELECT c.comment_id, c.owner_id, c.deleted_yn, c.comment_id AS root_comment_id, ARRAY[c.comment_id] AS comment_path FROM tb_common_comment c WHERE c.tenant_id = #{tenantId} AND c.owner_type = 'APPROVAL' AND c.owner_id IN
#{ownerId}
AND c.comment_type = 'USER' AND c.parent_comment_id IS NULL UNION ALL SELECT child.comment_id, child.owner_id, child.deleted_yn, tree.root_comment_id, tree.comment_path || child.comment_id FROM tb_common_comment child JOIN user_comment_tree tree ON tree.comment_id = child.parent_comment_id WHERE child.tenant_id = #{tenantId} AND child.owner_type = 'APPROVAL' AND child.owner_id IN
#{ownerId}
AND child.comment_type = 'USER' AND NOT child.comment_id = ANY(tree.comment_path) ), visible_user_roots AS ( SELECT owner_id, root_comment_id AS comment_id FROM user_comment_tree GROUP BY owner_id, root_comment_id HAVING BOOL_OR(deleted_yn = 'N') ), system_roots AS ( SELECT owner_id, comment_id FROM tb_common_comment WHERE tenant_id = #{tenantId} AND owner_type = 'APPROVAL' AND owner_id IN
#{ownerId}
AND comment_type = 'SYSTEM' AND parent_comment_id IS NULL AND deleted_yn = 'N' ), stream_roots AS ( SELECT owner_id, comment_id FROM visible_user_roots UNION ALL SELECT owner_id, comment_id FROM system_roots ) SELECT owner_id AS "ownerId", COUNT(*) AS "totalCount" FROM stream_roots GROUP BY owner_id

SELECT COUNT(*)
FROM tb_common_comment
WHERE tenant_id = #{tenantId}
  AND owner_type = #{ownerType}
  AND owner_id = #{ownerId}
  AND parent_comment_id IS NULL
  AND deleted_yn = 'N'

SELECT c.comment_id, c.tenant_id, c.owner_type, c.owner_id, c.parent_comment_id,
       c.content, c.comment_type, c.event_type, c.writer_id, c.writer_name, c.last_modified_by,
       c.last_modified_by_name, c.deleted_yn, c.created_at, c.updated_at,

FROM tb_common_comment c

WHERE c.tenant_id = #{tenantId}
  AND c.comment_id = #{commentId}
  AND c.owner_type = 'APPROVAL'
  AND c.owner_id = #{ownerId}
  AND c.comment_type = 'USER'
  AND c.deleted_yn = 'N'

mapper.update:
UPDATE tb_common_comment
SET content = #{content},
    last_modified_by = #{actorId},
    last_modified_by_name = #{actorName},
    updated_at = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId}
  AND comment_id = #{commentId}
  AND owner_type = 'APPROVAL'
  AND owner_id = #{ownerId}
  AND writer_id = #{actorId}
  AND comment_type = 'USER'
  AND deleted_yn = 'N'

UPDATE tb_common_comment
SET deleted_yn = 'Y',
    last_modified_by = #{actorId},
    last_modified_by_name = #{actorName},
    updated_at = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId}
  AND comment_id = #{commentId}
  AND owner_type = 'APPROVAL'
  AND owner_id = #{ownerId}
  AND writer_id = #{actorId}
  AND comment_type = 'USER'
  AND deleted_yn = 'N'
